settings.custom_css:
&, & img {
  object-fit: contain;
  height: 145px;
}
@media (min-width: 920px) {
  &, & img {
    object-fit: contain;
    height: 470px;
  }
}
@media (min-width: 1700px) {
  &,
  & img {
    height: 500px;
  }
}

