& a {
  text-transform: uppercase;
  border: 2px solid #b68b32;
  height:50px;
  width:185px;
   font-size: 14px !important;
   padding: 0 !important;
}
@media (min-width: 920px) {
  &  {
    margin-top:8px !important;
  }
  &  a{
    margin-bottom:0 !important;
  }
}

#SECTION_ID .content-builder__left{
  width: 100%;
  background:white;
  max-width: 56rem;
  padding:30px 0;
  margin:auto;
  gap:0;
}
#SECTION_ID .content-builder__right {
  display: none;
}

& {
  color: rgb(136, 146, 146);
  border: 1px solid rgb(182, 139, 50);
  width: fit-content;
  padding: 0 5px;
  margin-top: 5px;
  margin-bottom: 10px;
}

@media (min-width: 920px) {
  & {
    font-size: 22px;
  }
}

.product-card__material{
display:none;
}
.product-card__reviews{
  display:none;
}
#SECTION_ID .product-card__content {
  padding: 0;
}
#SECTION_ID .product-card__price,.product-card__price_mobile {
  border:none;
  font-weight:400;
  margin-bottom:5px;
  color: rgb(195, 54, 49);
}
@media (min-width: 920px) {
  #SECTION_ID .main-collection-products__grid {
    padding-left: 0;
    padding-right: 0;
    padding-top: 1.5rem;
  }
 .product-card__image-wrapper {
    height: 18rem;
  }
.product-card__title {
  font-size: 0.7rem;
}
#SECTION_ID .product-card__price {
  font-size: 22px;
  margin-bottom:10px;
}
}

